// Intent Parser: 자연어 입력을 IntentType으로 변환
// 9종 의도 + 15개 패턴 매칭

enum IntentType {
    Compute,
    Transform,
    Filter,
    Aggregate,
    IO,
    Control,
    Validate,
    Format,
    Unknown
}

struct Intent {
    intent_type: IntentType,
    raw_input: String,
    params: Vec<String>,
    confidence: f32,
    matched_keywords: Vec<String>
}

struct PatternRule {
    keywords: Vec<String>,
    intent_type: IntentType,
    weight: f32
}

struct IntentParser {
    rules: Vec<PatternRule>,
    min_confidence: f32
}

fn create_default_rules() -> Vec<PatternRule> {
    let rules = vec![
        // Compute templates
        PatternRule {
            keywords: vec!["더하기", "더해", "합", "add", "plus"],
            intent_type: IntentType::Compute,
            weight: 1.0
        },
        PatternRule {
            keywords: vec!["곱하기", "곱해", "곱셈", "multiply", "times"],
            intent_type: IntentType::Compute,
            weight: 1.0
        },
        PatternRule {
            keywords: vec!["빼기", "빼", "차", "subtract", "minus"],
            intent_type: IntentType::Compute,
            weight: 1.0
        },
        PatternRule {
            keywords: vec!["나누기", "나눠", "division", "divide"],
            intent_type: IntentType::Compute,
            weight: 1.0
        },
        PatternRule {
            keywords: vec!["거듭제곱", "제곱", "power", "pow"],
            intent_type: IntentType::Compute,
            weight: 0.95
        },
        // Transform templates
        PatternRule {
            keywords: vec!["대문자", "대문", "uppercase", "upper"],
            intent_type: IntentType::Transform,
            weight: 1.0
        },
        PatternRule {
            keywords: vec!["소문자", "소문", "lowercase", "lower"],
            intent_type: IntentType::Transform,
            weight: 1.0
        },
        PatternRule {
            keywords: vec!["역순", "뒤집기", "reverse", "reversed"],
            intent_type: IntentType::Transform,
            weight: 1.0
        },
        // Filter templates
        PatternRule {
            keywords: vec!["필터", "필터링", "걸러", "filter"],
            intent_type: IntentType::Filter,
            weight: 0.9
        },
        PatternRule {
            keywords: vec!["짝수", "even"],
            intent_type: IntentType::Filter,
            weight: 1.0
        },
        PatternRule {
            keywords: vec!["양수", "positive"],
            intent_type: IntentType::Filter,
            weight: 1.0
        },
        PatternRule {
            keywords: vec!["초과", "보다 크", "greater"],
            intent_type: IntentType::Filter,
            weight: 0.95
        },
        // Aggregate templates
        PatternRule {
            keywords: vec!["평균", "average", "avg", "mean"],
            intent_type: IntentType::Aggregate,
            weight: 1.0
        },
        PatternRule {
            keywords: vec!["최대", "최댓값", "max", "maximum"],
            intent_type: IntentType::Aggregate,
            weight: 1.0
        },
        PatternRule {
            keywords: vec!["최소", "최솟값", "min", "minimum"],
            intent_type: IntentType::Aggregate,
            weight: 1.0
        },
        // Control templates
        PatternRule {
            keywords: vec!["반복", "루프", "loop", "for"],
            intent_type: IntentType::Control,
            weight: 0.95
        },
        // IO, Validate, Format (placeholder)
        PatternRule {
            keywords: vec!["파일", "읽기", "저장", "file", "read", "write"],
            intent_type: IntentType::IO,
            weight: 0.9
        },
        PatternRule {
            keywords: vec!["검증", "확인", "검사", "validate", "check"],
            intent_type: IntentType::Validate,
            weight: 0.9
        },
        PatternRule {
            keywords: vec!["형식", "포맷", "형태", "format"],
            intent_type: IntentType::Format,
            weight: 0.9
        }
    ];
    rules
}

fn extract_numbers(input: String) -> Vec<String> {
    let chars = input.chars();
    let mut numbers = vec![];
    let mut current = String::new();

    for c in chars {
        if c.is_numeric() {
            current.push(c);
        } else {
            if current.len() > 0 {
                numbers.push(current.clone());
                current = String::new();
            }
        }
    }

    if current.len() > 0 {
        numbers.push(current);
    }

    numbers
}

fn extract_nouns(input: String) -> Vec<String> {
    // 간단한 한글 명사 추출: 2-4글자의 연속된 한글 문자
    let words = input.split(' ').collect::<Vec<&str>>();
    let nouns = words.iter()
        .filter(|w| w.len() >= 2 && w.len() <= 8)
        .map(|w| w.to_string())
        .collect::<Vec<String>>();
    nouns
}

fn calculate_confidence(matched_count: i32, total_rules: i32, matched_weights_sum: f32) -> f32 {
    let base_score = (matched_count as f32) / (total_rules as f32).max(1.0);
    let weighted_score = matched_weights_sum / matched_count.max(1) as f32;
    (base_score * 0.3) + (weighted_score * 0.7)
}

impl IntentParser {
    fn new(min_confidence: f32) -> IntentParser {
        IntentParser {
            rules: create_default_rules(),
            min_confidence
        }
    }

    fn parse(self, input: String) -> Intent {
        let lower_input = input.to_lowercase();
        let mut matched_keywords = vec![];
        let mut matched_intent = IntentType::Unknown;
        let mut max_weight = 0.0;
        let mut matched_count = 0;
        let mut matched_weights_sum = 0.0;

        for rule in &self.rules {
            for keyword in &rule.keywords {
                if lower_input.contains(keyword.as_str()) {
                    matched_keywords.push(keyword.clone());
                    matched_count = matched_count + 1;
                    matched_weights_sum = matched_weights_sum + rule.weight;

                    if rule.weight > max_weight {
                        max_weight = rule.weight;
                        matched_intent = rule.intent_type.clone();
                    }
                }
            }
        }

        let confidence = calculate_confidence(matched_count, 19, matched_weights_sum);
        let params = extract_numbers(input.clone());

        Intent {
            intent_type: matched_intent,
            raw_input: input,
            params,
            confidence,
            matched_keywords
        }
    }
}

fn parse_intent(input: String) -> Intent {
    let parser = IntentParser::new(0.5);
    parser.parse(input)
}

fn parse_intent_with_confidence(input: String, min_conf: f32) -> Result<Intent, String> {
    let parser = IntentParser::new(min_conf);
    let intent = parser.parse(input);

    if intent.confidence >= min_conf {
        Result::Ok(intent)
    } else {
        Result::Err(format!("Confidence too low: {}", intent.confidence))
    }
}

fn intent_type_to_string(intent_type: IntentType) -> String {
    match intent_type {
        IntentType::Compute => "Compute".to_string(),
        IntentType::Transform => "Transform".to_string(),
        IntentType::Filter => "Filter".to_string(),
        IntentType::Aggregate => "Aggregate".to_string(),
        IntentType::IO => "IO".to_string(),
        IntentType::Control => "Control".to_string(),
        IntentType::Validate => "Validate".to_string(),
        IntentType::Format => "Format".to_string(),
        IntentType::Unknown => "Unknown".to_string()
    }
}

