// Code Generator: Intent를 FV-Lang 코드로 변환
// 15개 템플릿 기반 코드 생성

use crate::phase2::intent_parser::*;

enum TypeInference {
    Int32,
    Float64,
    Bool,
    String,
    VecInt32,
    Unknown
}

struct CodeTemplate {
    id: String,
    intent_type: IntentType,
    template_code: String,
    input_type: String,
    output_type: String,
    param_count: i32
}

struct GeneratedCode {
    fn_name: String,
    full_code: String,
    input_type: String,
    output_type: String,
    param_count: i32,
    intent: Intent
}

struct CodeGenerator {
    templates: Vec<CodeTemplate>,
    fn_counter: i32
}

fn create_templates() -> Vec<CodeTemplate> {
    vec![
        // Compute templates
        CodeTemplate {
            id: "tpl_add".to_string(),
            intent_type: IntentType::Compute,
            template_code: "fn add_${counter}(a: i32, b: i32) -> i32 { a + b }".to_string(),
            input_type: "i32, i32".to_string(),
            output_type: "i32".to_string(),
            param_count: 2
        },
        CodeTemplate {
            id: "tpl_mul".to_string(),
            intent_type: IntentType::Compute,
            template_code: "fn mul_${counter}(a: i32, b: i32) -> i32 { a * b }".to_string(),
            input_type: "i32, i32".to_string(),
            output_type: "i32".to_string(),
            param_count: 2
        },
        CodeTemplate {
            id: "tpl_sub".to_string(),
            intent_type: IntentType::Compute,
            template_code: "fn sub_${counter}(a: i32, b: i32) -> i32 { a - b }".to_string(),
            input_type: "i32, i32".to_string(),
            output_type: "i32".to_string(),
            param_count: 2
        },
        CodeTemplate {
            id: "tpl_div".to_string(),
            intent_type: IntentType::Compute,
            template_code: "fn div_${counter}(a: i32, b: i32) -> i32 { a / b }".to_string(),
            input_type: "i32, i32".to_string(),
            output_type: "i32".to_string(),
            param_count: 2
        },
        CodeTemplate {
            id: "tpl_pow".to_string(),
            intent_type: IntentType::Compute,
            template_code: "fn pow_${counter}(base: i32, exp: i32) -> i32 { let mut result = 1; for _ in 0..exp { result = result * base }; result }".to_string(),
            input_type: "i32, i32".to_string(),
            output_type: "i32".to_string(),
            param_count: 2
        },
        // Transform templates
        CodeTemplate {
            id: "tpl_to_upper".to_string(),
            intent_type: IntentType::Transform,
            template_code: "fn to_upper_${counter}(s: String) -> String { s.to_uppercase() }".to_string(),
            input_type: "String".to_string(),
            output_type: "String".to_string(),
            param_count: 1
        },
        CodeTemplate {
            id: "tpl_to_lower".to_string(),
            intent_type: IntentType::Transform,
            template_code: "fn to_lower_${counter}(s: String) -> String { s.to_lowercase() }".to_string(),
            input_type: "String".to_string(),
            output_type: "String".to_string(),
            param_count: 1
        },
        CodeTemplate {
            id: "tpl_reverse".to_string(),
            intent_type: IntentType::Transform,
            template_code: "fn reverse_${counter}(s: String) -> String { s.chars().rev().collect() }".to_string(),
            input_type: "String".to_string(),
            output_type: "String".to_string(),
            param_count: 1
        },
        // Filter templates
        CodeTemplate {
            id: "tpl_filter_even".to_string(),
            intent_type: IntentType::Filter,
            template_code: "fn filter_even_${counter}(nums: Vec<i32>) -> Vec<i32> { nums.iter().filter(|x| *x % 2 == 0).map(|x| *x).collect() }".to_string(),
            input_type: "Vec<i32>".to_string(),
            output_type: "Vec<i32>".to_string(),
            param_count: 1
        },
        CodeTemplate {
            id: "tpl_filter_pos".to_string(),
            intent_type: IntentType::Filter,
            template_code: "fn filter_pos_${counter}(nums: Vec<i32>) -> Vec<i32> { nums.iter().filter(|x| *x > 0).map(|x| *x).collect() }".to_string(),
            input_type: "Vec<i32>".to_string(),
            output_type: "Vec<i32>".to_string(),
            param_count: 1
        },
        CodeTemplate {
            id: "tpl_filter_gt".to_string(),
            intent_type: IntentType::Filter,
            template_code: "fn filter_gt_${counter}(nums: Vec<i32>, threshold: i32) -> Vec<i32> { nums.iter().filter(|x| *x > threshold).map(|x| *x).collect() }".to_string(),
            input_type: "Vec<i32>, i32".to_string(),
            output_type: "Vec<i32>".to_string(),
            param_count: 2
        },
        // Aggregate templates
        CodeTemplate {
            id: "tpl_avg".to_string(),
            intent_type: IntentType::Aggregate,
            template_code: "fn avg_${counter}(nums: Vec<i32>) -> i32 { if nums.len() == 0 { 0 } else { nums.iter().sum::<i32>() / nums.len() as i32 } }".to_string(),
            input_type: "Vec<i32>".to_string(),
            output_type: "i32".to_string(),
            param_count: 1
        },
        CodeTemplate {
            id: "tpl_max".to_string(),
            intent_type: IntentType::Aggregate,
            template_code: "fn max_${counter}(nums: Vec<i32>) -> i32 { *nums.iter().max().unwrap_or(&0) }".to_string(),
            input_type: "Vec<i32>".to_string(),
            output_type: "i32".to_string(),
            param_count: 1
        },
        CodeTemplate {
            id: "tpl_min".to_string(),
            intent_type: IntentType::Aggregate,
            template_code: "fn min_${counter}(nums: Vec<i32>) -> i32 { *nums.iter().min().unwrap_or(&0) }".to_string(),
            input_type: "Vec<i32>".to_string(),
            output_type: "i32".to_string(),
            param_count: 1
        },
        // Control templates
        CodeTemplate {
            id: "tpl_range_loop".to_string(),
            intent_type: IntentType::Control,
            template_code: "fn range_loop_${counter}(n: i32) { for i in 0..n { let _ = i; } }".to_string(),
            input_type: "i32".to_string(),
            output_type: "()".to_string(),
            param_count: 1
        }
    ]
}

fn infer_type(value: String) -> TypeInference {
    let lower_val = value.to_lowercase();

    if lower_val.contains("string") || lower_val.contains("문자") {
        return TypeInference::String;
    }

    if lower_val.contains("float") || lower_val.contains("f64") || lower_val.contains("소수") {
        return TypeInference::Float64;
    }

    if lower_val.contains("bool") || lower_val.contains("참") || lower_val.contains("거짓") {
        return TypeInference::Bool;
    }

    if lower_val.contains("vec") || lower_val.contains("배열") || lower_val.contains("리스트") {
        return TypeInference::VecInt32;
    }

    // Default to i32 if numbers detected
    if value.chars().any(|c| c.is_numeric()) {
        return TypeInference::Int32;
    }

    TypeInference::Unknown
}

fn type_to_string(ty: TypeInference) -> String {
    match ty {
        TypeInference::Int32 => "i32".to_string(),
        TypeInference::Float64 => "f64".to_string(),
        TypeInference::Bool => "bool".to_string(),
        TypeInference::String => "String".to_string(),
        TypeInference::VecInt32 => "Vec<i32>".to_string(),
        TypeInference::Unknown => "unknown".to_string()
    }
}

impl CodeGenerator {
    fn new() -> CodeGenerator {
        CodeGenerator {
            templates: create_templates(),
            fn_counter: 0
        }
    }

    fn find_matching_template(self, intent: Intent) -> Option<CodeTemplate> {
        for template in &self.templates {
            if template.intent_type.matches(&intent.intent_type) {
                return Option::Some(template.clone());
            }
        }
        Option::None
    }

    fn generate(mut self, intent: Intent) -> Result<GeneratedCode, String> {
        // Find matching template based on intent
        let template_opt = self.find_matching_template(intent.clone());

        match template_opt {
            Option::None => {
                Result::Err("No matching template for intent".to_string())
            },
            Option::Some(template) => {
                self.fn_counter = self.fn_counter + 1;

                let fn_name = format!("fn_{}", self.fn_counter);
                let code = template.template_code.replace("${counter}", &self.fn_counter.to_string());

                Result::Ok(GeneratedCode {
                    fn_name: fn_name,
                    full_code: code,
                    input_type: template.input_type,
                    output_type: template.output_type,
                    param_count: template.param_count,
                    intent: intent
                })
            }
        }
    }
