        CodeTemplate {
            id: "tpl_sub".to_string(),
            intent_type: IntentType::Compute,
            template_code: "fn sub_${counter}(a: i32, b: i32) -> i32 { a - b }".to_string(),
            input_type: "i32, i32".to_string(),
            output_type: "i32".to_string(),
            param_count: 2
