        },
        CodeTemplate {
            id: "tpl_pow".to_string(),
            intent_type: IntentType::Compute,
            template_code: "fn pow_${counter}(base: i32, exp: i32) -> i32 { let mut result = 1; for _ in 0..exp { result = result * base }; result }".to_string(),
            input_type: "i32, i32".to_string(),
            output_type: "i32".to_string(),
            param_count: 2
