            input_type: "Vec<i32>".to_string(),
            output_type: "i32".to_string(),
            param_count: 1
        },
        // Control templates
        CodeTemplate {
            id: "tpl_range_loop".to_string(),
            intent_type: IntentType::Control,
            template_code: "fn range_loop_${counter}(n: i32) { for i in 0..n { let _ = i; } }".to_string(),
            input_type: "i32".to_string(),
            output_type: "()".to_string(),
            param_count: 1
        }
    ]
}

fn infer_type(value: String) -> TypeInference {
    let lower_val = value.to_lowercase();

    if lower_val.contains("string") || lower_val.contains("문자") {
        return TypeInference::String;
    }

    if lower_val.contains("float") || lower_val.contains("f64") || lower_val.contains("소수") {
        return TypeInference::Float64;
    }

    if lower_val.contains("bool") || lower_val.contains("참") || lower_val.contains("거짓") {
        return TypeInference::Bool;
    }

    if lower_val.contains("vec") || lower_val.contains("배열") || lower_val.contains("리스트") {
        return TypeInference::VecInt32;
    }

    // Default to i32 if numbers detected
    if value.chars().any(|c| c.is_numeric()) {
        return TypeInference::Int32;
    }

    TypeInference::Unknown
}

fn type_to_string(ty: TypeInference) -> String {
    match ty {
        TypeInference::Int32 => "i32".to_string(),
        TypeInference::Float64 => "f64".to_string(),
        TypeInference::Bool => "bool".to_string(),
        TypeInference::String => "String".to_string(),
        TypeInference::VecInt32 => "Vec<i32>".to_string(),
        TypeInference::Unknown => "unknown".to_string()
    }
}

impl CodeGenerator {
    fn new() -> CodeGenerator {
        CodeGenerator {
            templates: create_templates(),
            fn_counter: 0
        }
    }

    fn find_matching_template(self, intent: Intent) -> Option<CodeTemplate> {
        for template in &self.templates {
            if template.intent_type.matches(&intent.intent_type) {
                return Option::Some(template.clone());
            }
        }
        Option::None
    }

    fn generate(mut self, intent: Intent) -> Result<GeneratedCode, String> {
        // Find matching template based on intent
        let template_opt = self.find_matching_template(intent.clone());

        match template_opt {
            Option::None => {
                Result::Err("No matching template for intent".to_string())
            },
            Option::Some(template) => {
                self.fn_counter = self.fn_counter + 1;

                let fn_name = format!("fn_{}", self.fn_counter);
                let code = template.template_code.replace("${counter}", &self.fn_counter.to_string());

                Result::Ok(GeneratedCode {
                    fn_name: fn_name,
                    full_code: code,
                    input_type: template.input_type,
                    output_type: template.output_type,
                    param_count: template.param_count,
                    intent: intent
                })
            }
        }
    }
}

fn generate_code(intent: Intent) -> Result<GeneratedCode, String> {
    let generator = CodeGenerator::new();
    generator.generate(intent)
}

fn generate_code_with_params(intent: Intent, params: Vec<String>) -> Result<GeneratedCode, String> {
    let mut intent = intent;
    intent.params = params;

    let generator = CodeGenerator::new();
    generator.generate(intent)
}

// Trait implementation placeholder for IntentType
trait IntentTypeMatcher {
    fn matches(&self, other: &IntentType) -> bool;
}

impl IntentTypeMatcher for IntentType {
    fn matches(&self, other: &IntentType) -> bool {
        match (self, other) {
            (IntentType::Compute, IntentType::Compute) => true,
            (IntentType::Transform, IntentType::Transform) => true,
            (IntentType::Filter, IntentType::Filter) => true,
            (IntentType::Aggregate, IntentType::Aggregate) => true,
            (IntentType::Control, IntentType::Control) => true,
            _ => false
        }
    }
}

// Helper trait for cloning
trait CodeTemplateClone {
    fn clone(&self) -> CodeTemplate;
}

impl CodeTemplateClone for CodeTemplate {
    fn clone(&self) -> CodeTemplate {
        CodeTemplate {
            id: self.id.clone(),
            intent_type: self.intent_type.clone(),
            template_code: self.template_code.clone(),
            input_type: self.input_type.clone(),
            output_type: self.output_type.clone(),
            param_count: self.param_count
        }
    }
}

