            id: format!("input_{}", i),
            label: format!("Input {}", i + 1),
            node_type: NodeType::Input,
            inputs: vec![],
            outputs: vec![
                NodePort {
                    port_id: format!("out_{}", i),
                    port_name: "output".to_string(),
                    port_type: "i32".to_string()
                }
            ],
            x: 50.0,
            y: y_offset,
            color: get_node_color(NodeType::Input)
        };

        nodes.push(node);
        y_offset = y_offset + 80.0;
    }

    nodes
}

fn create_process_node(fn_name: String, input_type: String, output_type: String) -> Node {
    Node {
        id: "process_0".to_string(),
        label: fn_name,
        node_type: NodeType::Process,
        inputs: vec![
            NodePort {
                port_id: "in_0".to_string(),
                port_name: "input".to_string(),
                port_type: input_type
            }
        ],
        outputs: vec![
            NodePort {
                port_id: "out_0".to_string(),
                port_name: "output".to_string(),
                port_type: output_type
            }
        ],
        x: 250.0,
        y: 100.0,
        color: get_node_color(NodeType::Process)
    }
}

fn create_output_node(output_type: String) -> Node {
    Node {
        id: "output_0".to_string(),
        label: "Output".to_string(),
        node_type: NodeType::Output,
        inputs: vec![
            NodePort {
                port_id: "in_0".to_string(),
                port_name: "result".to_string(),
                port_type: output_type
            }
        ],
        outputs: vec![],
        x: 450.0,
        y: 100.0,
        color: get_node_color(NodeType::Output)
    }
}

fn create_edges(param_count: i32) -> Vec<Edge> {
    let mut edges = vec![];

    // Connect inputs to process
    for i in 0..param_count {
        edges.push(Edge {
            from_node: format!("input_{}", i),
            from_port: format!("out_{}", i),
            to_node: "process_0".to_string(),
            to_port: "in_0".to_string(),
            edge_type: "data".to_string()
        });
    }

    // Connect process to output
    edges.push(Edge {
        from_node: "process_0".to_string(),
        from_port: "out_0".to_string(),
        to_node: "output_0".to_string(),
        to_port: "in_0".to_string(),
        edge_type: "data".to_string()
    });

    edges
}

impl NodeVisualizer {
    fn from_generated_code(code: GeneratedCode) -> NodeVisualizer {
        let mut nodes = create_input_nodes(code.param_count, code.input_type.clone());
        nodes.push(create_process_node(code.fn_name, code.input_type, code.output_type.clone()));
        nodes.push(create_output_node(code.output_type));

        let edges = create_edges(code.param_count);

        let graph = NodeGraph {
            nodes,
            edges,
            title: "Function Flow Graph".to_string(),
            width: 600,
            height: 400
        };

        NodeVisualizer { graph }
    }

    fn render_html(self) -> String {
        let mut html = String::new();

        html.push_str("<!DOCTYPE html>\n");
        html.push_str("<html>\n");
        html.push_str("<head>\n");
        html.push_str("  <meta charset=\"utf-8\">\n");
        html.push_str("  <title>Node Graph Visualizer</title>\n");
        html.push_str("  <style>\n");
        html.push_str("    body { font-family: monospace; background: #282a36; color: #f8f8f2; }\n");
        html.push_str("    svg { border: 1px solid #44475a; background: #1e1e1e; }\n");
        html.push_str("    .node-input { fill: #50fa7b; }\n");
        html.push_str("    .node-process { fill: #8be9fd; }\n");
        html.push_str("    .node-output { fill: #ff79c6; }\n");
        html.push_str("    .node-label { font-size: 12px; text-anchor: middle; }\n");
        html.push_str("    .edge-line { stroke: #f8f8f2; stroke-width: 2; fill: none; }\n");
        html.push_str("  </style>\n");
        html.push_str("</head>\n");
        html.push_str("<body>\n");
        html.push_str("  <h2>Node Graph: ");
        html.push_str(self.graph.title.as_str());
        html.push_str("</h2>\n");
        html.push_str("  <svg width=\"");
        html.push_str(&self.graph.width.to_string());
        html.push_str("\" height=\"");
        html.push_str(&self.graph.height.to_string());
        html.push_str("\">\n");

        // Draw edges
        for edge in &self.graph.edges {
            let from_node_opt = self.graph.nodes.iter()
                .find(|n| n.id == edge.from_node);
            let to_node_opt = self.graph.nodes.iter()
                .find(|n| n.id == edge.to_node);

            match (from_node_opt, to_node_opt) {
                (Some(from_node), Some(to_node)) => {
                    html.push_str("    <line class=\"edge-line\" x1=\"");
                    html.push_str(&(from_node.x + 50.0).to_string());
                    html.push_str("\" y1=\"");
                    html.push_str(&(from_node.y + 20.0).to_string());
                    html.push_str("\" x2=\"");
                    html.push_str(&(to_node.x - 30.0).to_string());
                    html.push_str("\" y2=\"");
                    html.push_str(&(to_node.y + 20.0).to_string());
                    html.push_str("\" />\n");
                },
                _ => {}
            }
        }

        // Draw nodes
        for node in &self.graph.nodes {
            let node_class = format!("node-{}", get_node_type_string(node.node_type.clone()));

            html.push_str("    <rect class=\"");
            html.push_str(&node_class);
            html.push_str("\" x=\"");
            html.push_str(&(node.x - 30.0).to_string());
            html.push_str("\" y=\"");
            html.push_str(&(node.y - 15.0).to_string());
            html.push_str("\" width=\"60\" height=\"40\" rx=\"5\" />\n");

            html.push_str("    <text class=\"node-label\" x=\"");
            html.push_str(&node.x.to_string());
            html.push_str("\" y=\"");
            html.push_str(&(node.y + 5.0).to_string());
            html.push_str("\">");
            html.push_str(&node.label);
            html.push_str("</text>\n");
        }

        html.push_str("  </svg>\n");
        html.push_str("</body>\n");
        html.push_str("</html>\n");

        html
    }

    fn render_ascii(self) -> String {
        let mut ascii = String::new();

        ascii.push_str("╔════════════════════════════════════════════════════════╗\n");
        ascii.push_str("║         Node Graph Visualization (ASCII Art)          ║\n");
        ascii.push_str("╚════════════════════════════════════════════════════════╝\n\n");

        // Input nodes
        for i in 0..self.graph.nodes.len() {
            let node = &self.graph.nodes[i];
            let node_type_str = get_node_type_string(node.node_type.clone());

            ascii.push_str("[");
            ascii.push_str(&node_type_str);
            ascii.push_str(" ");
            ascii.push_str(&node.label);
            ascii.push_str("]\n");

            if i < self.graph.nodes.len() - 1 {
                ascii.push_str("    ↓\n");
            }
        }

        ascii.push_str("\n");
        ascii.push_str("Edges: ");
        ascii.push_str(&self.graph.edges.len().to_string());
        ascii.push_str(" connections\n");

        ascii
    }
}

fn visualize_code(code: GeneratedCode) -> NodeGraph {
    let visualizer = NodeVisualizer::from_generated_code(code);
    visualizer.graph
}

fn render_graph_html(graph: NodeGraph) -> String {
    let visualizer = NodeVisualizer { graph };
    visualizer.render_html()
}

fn render_graph_ascii(graph: NodeGraph) -> String {
    let visualizer = NodeVisualizer { graph };
    visualizer.render_ascii()
}

// Helper trait for cloning
trait NodeTypeClone {
    fn clone(&self) -> NodeType;
}

impl NodeTypeClone for NodeType {
    fn clone(&self) -> NodeType {
        match self {
            NodeType::Input => NodeType::Input,
            NodeType::Process => NodeType::Process,
            NodeType::Output => NodeType::Output,
            NodeType::Conditional => NodeType::Conditional,
            NodeType::Loop => NodeType::Loop,
            NodeType::Constant => NodeType::Constant
        }
    }
}

