// Korean NLP: 한국어 자연어 처리 강화
// 문맥 기반 파라미터 추론, 변수명 자동 생성, 다국어 지원

use crate::phase2::intent_parser::*;

enum Entity {
    Number(i32),
    Range(i32, i32),
    String(String),
    Array(Vec<String>),
    Unknown
}

enum Language {
    Korean,
    English,
    Japanese,
    Chinese,
    Unknown
}

struct ContextAnalyzer {
    input: String,
    language: Language,
    detected_entities: Vec<Entity>,
    inferred_types: Vec<String>,
    variable_names: Vec<String>,
    confidence: f32
}

struct MultilingualKeywords {
    korean: Vec<String>,
    english: Vec<String>,
    japanese: Vec<String>,
    chinese: Vec<String>
}

fn detect_language(input: String) -> Language {
    let lower = input.to_lowercase();

    // 한글 감지 (간단한 휴리스틱)
    if input.chars().any(|c| c as u32 >= 0xAC00 && c as u32 <= 0xD7A3) {
        return Language::Korean;
    }

    // 일본어 감지
    if input.chars().any(|c| c as u32 >= 0x3040 && c as u32 <= 0x309F) {
        return Language::Japanese;
    }

    // 중국어 감지
    if input.chars().any(|c| c as u32 >= 0x4E00 && c as u32 <= 0x9FFF) {
        return Language::Chinese;
    }

    Language::English
}

fn extract_numbers_from_context(input: String) -> Vec<i32> {
    let mut numbers = vec![];
    let mut current = String::new();

    for c in input.chars() {
        if c.is_numeric() {
            current.push(c);
        } else {
            if current.len() > 0 {
                match current.parse::<i32>() {
                    Ok(num) => numbers.push(num),
                    Err(_) => {}
                }
                current = String::new();
            }
        }
    }

    if current.len() > 0 {
        match current.parse::<i32>() {
            Ok(num) => numbers.push(num),
            Err(_) => {}
        }
    }

    numbers
}

fn detect_range(input: String) -> Option<(i32, i32)> {
    // "1부터 10까지", "1~10", "1-10" 패턴 감지
    if input.contains("부터") && input.contains("까지") {
        let numbers = extract_numbers_from_context(input);
        if numbers.len() >= 2 {
            return Option::Some((numbers[0], numbers[1]));
        }
    }

    if input.contains("~") || input.contains("-") {
        let numbers = extract_numbers_from_context(input);
        if numbers.len() >= 2 {
            return Option::Some((numbers[0], numbers[1]));
        }
    }

    Option::None
}

fn detect_array(input: String) -> bool {
    input.contains("배열") || input.contains("리스트") ||
    input.contains("array") || input.contains("list") ||
    input.contains("vec")
}

fn infer_entity(input: String) -> Entity {
    // 범위 감지
    match detect_range(input.clone()) {
        Option::Some((start, end)) => return Entity::Range(start, end),
        Option::None => {}
    }

    // 배열 감지
    if detect_array(input.clone()) {
        return Entity::Array(vec![]);
    }

    // 숫자 감지
    let numbers = extract_numbers_from_context(input.clone());
    if numbers.len() > 0 {
        return Entity::Number(numbers[0]);
    }

    // 문자열
    if input.len() > 0 {
        return Entity::String(input);
    }

    Entity::Unknown
}

fn generate_variable_name(entity: Entity, context: String) -> String {
    match entity {
        Entity::Number(_) => "num".to_string(),
        Entity::Range(_, _) => "range".to_string(),
        Entity::String(_) => "text".to_string(),
        Entity::Array(_) => "items".to_string(),
        Entity::Unknown => "value".to_string()
    }
}

fn semantic_name_suggestions(context: String) -> Vec<String> {
    // 문맥 기반 변수명 추천 (상위 3개)
    let mut suggestions = vec![];

    if context.contains("사용자") {
        suggestions.push("users".to_string());
        suggestions.push("user_list".to_string());
        suggestions.push("people".to_string());
    } else if context.contains("숫자") {
        suggestions.push("numbers".to_string());
        suggestions.push("values".to_string());
        suggestions.push("nums".to_string());
    } else if context.contains("문자") {
        suggestions.push("text".to_string());
        suggestions.push("strings".to_string());
        suggestions.push("chars".to_string());
    } else {
        suggestions.push("data".to_string());
        suggestions.push("items".to_string());
        suggestions.push("result".to_string());
    }

    suggestions
}

impl ContextAnalyzer {
    fn new(input: String) -> ContextAnalyzer {
