        ExecutionStatus::Skipped => "skipped".to_string()
    }
}

fn create_dynamic_node(id: String, label: String) -> DynamicNode {
    DynamicNode {
        id,
        label,
        value: Option::None,
        status: ExecutionStatus::Pending,
        execution_time_ms: 0,
        color: get_status_color(ExecutionStatus::Pending)
    }
}

fn update_node_status(mut node: DynamicNode, status: ExecutionStatus) -> DynamicNode {
    node.status = status;
    node.color = get_status_color(status);
    node
}

fn update_node_value(mut node: DynamicNode, value: String) -> DynamicNode {
    node.value = Option::Some(value);
    node
}

fn update_node_execution_time(mut node: DynamicNode, time_ms: i32) -> DynamicNode {
    node.execution_time_ms = time_ms;
    node
}

impl DynamicGraph {
    fn new(title: String) -> DynamicGraph {
        DynamicGraph {
            nodes: vec![],
            edges: vec![],
            metadata: GraphMetadata {
                total_execution_time_ms: 0,
                total_memory_used_mb: 0,
                node_count: 0,
                completed_count: 0,
                error_count: 0
            },
            title
        }
    }

    fn add_node(mut self, node: DynamicNode) -> DynamicGraph {
        self.nodes.push(node);
        self.metadata.node_count = self.metadata.node_count + 1;
        self
    }

    fn add_edge(mut self, edge: Edge) -> DynamicGraph {
        self.edges.push(edge);
        self
    }

    fn update_node_status(mut self, node_id: String, status: ExecutionStatus) -> DynamicGraph {
        for node in &mut self.nodes {
            if node.id == node_id {
                node.status = status;
                node.color = get_status_color(node.status.clone());

                if node.status == ExecutionStatus::Completed {
                    self.metadata.completed_count = self.metadata.completed_count + 1;
                } else if node.status == ExecutionStatus::Error {
                    self.metadata.error_count = self.metadata.error_count + 1;
                }
            }
        }
        self
    }

    fn update_node_value(mut self, node_id: String, value: String) -> DynamicGraph {
        for node in &mut self.nodes {
            if node.id == node_id {
                node.value = Option::Some(value);
            }
        }
        self
    }

    fn update_metadata(mut self, time_ms: i32, memory_mb: i32) -> DynamicGraph {
        self.metadata.total_execution_time_ms = time_ms;
        self.metadata.total_memory_used_mb = memory_mb;
        self
    }

    fn calculate_critical_path(self) -> Vec<String> {
        // 간단한 크리티컬 경로: 실행 시간 최대인 노드들
        let mut times = vec![];
        for node in &self.nodes {
            times.push((node.id.clone(), node.execution_time_ms));
        }

        // 시간순 정렬
        let mut critical = vec![];
        let mut max_time = 0;
        for (id, time) in times {
            if time >= max_time {
                max_time = time;
                critical.push(id);
            }
        }

        critical
    }

    fn render_html(self) -> String {
        let mut html = String::new();

        html.push_str("<!DOCTYPE html>\n");
        html.push_str("<html>\n");
        html.push_str("<head>\n");
        html.push_str("  <meta charset=\"utf-8\">\n");
        html.push_str("  <title>Dynamic Graph Visualizer</title>\n");
        html.push_str("  <style>\n");
        html.push_str("    body { font-family: monospace; background: #282a36; color: #f8f8f2; padding: 20px; }\n");
        html.push_str("    h1 { color: #8be9fd; }\n");
        html.push_str("    svg { border: 1px solid #44475a; background: #1e1e1e; }\n");
        html.push_str("    .metadata { margin-top: 20px; padding: 10px; background: #44475a; border-radius: 5px; }\n");
        html.push_str("    .info { display: flex; gap: 20px; flex-wrap: wrap; }\n");
        html.push_str("    .stat { padding: 10px; background: #6272a4; border-radius: 3px; }\n");
        html.push_str("    .stat-label { font-size: 12px; color: #a0a0a0; }\n");
        html.push_str("    .stat-value { font-size: 18px; color: #50fa7b; font-weight: bold; }\n");
        html.push_str("  </style>\n");
        html.push_str("</head>\n");
        html.push_str("<body>\n");

        html.push_str("  <h1>Dynamic Graph: ");
        html.push_str(&self.title);
        html.push_str("</h1>\n");

        // SVG 렌더링
        html.push_str("  <svg width=\"800\" height=\"500\">\n");

        // 엣지 렌더링
        for edge in &self.edges {
            let from_node = self.nodes.iter().find(|n| n.id == edge.from_node);
            let to_node = self.nodes.iter().find(|n| n.id == edge.to_node);

            match (from_node, to_node) {
                (Some(from), Some(to)) => {
                    html.push_str("    <line x1=\"");
                    html.push_str(&(from.id.len() as i32 * 50).to_string());
                    html.push_str("\" y1=\"100\" x2=\"");
                    html.push_str(&(to.id.len() as i32 * 50).to_string());
                    html.push_str("\" y2=\"100\" stroke=\"#f8f8f2\" stroke-width=\"2\" />\n");
                },
                _ => {}
            }
        }

        // 노드 렌더링
        let mut x_pos = 50;
        for node in &self.nodes {
            html.push_str("    <rect x=\"");
            html.push_str(&(x_pos - 30).to_string());
            html.push_str("\" y=\"70\" width=\"60\" height=\"60\" fill=\"");
            html.push_str(&node.color);
            html.push_str("\" rx=\"5\" />\n");

            html.push_str("    <text x=\"");
            html.push_str(&x_pos.to_string());
            html.push_str("\" y=\"105\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1e1e1e\">");
            html.push_str(&node.label);
            html.push_str("</text>\n");

            // 값 표시
            if let Option::Some(val) = &node.value {
                html.push_str("    <text x=\"");
                html.push_str(&x_pos.to_string());
                html.push_str("\" y=\"160\" text-anchor=\"middle\" font-size=\"11\" fill=\"#50fa7b\">");
                html.push_str(val);
                html.push_str("</text>\n");
            }

            x_pos = x_pos + 120;
        }

        html.push_str("  </svg>\n");

        // 메타데이터 표시
        html.push_str("  <div class=\"metadata\">\n");
        html.push_str("    <div class=\"info\">\n");

        html.push_str("      <div class=\"stat\">\n");
        html.push_str("        <div class=\"stat-label\">Total Time</div>\n");
        html.push_str("        <div class=\"stat-value\">");
        html.push_str(&self.metadata.total_execution_time_ms.to_string());
        html.push_str("ms</div>\n");
        html.push_str("      </div>\n");

        html.push_str("      <div class=\"stat\">\n");
        html.push_str("        <div class=\"stat-label\">Memory Used</div>\n");
        html.push_str("        <div class=\"stat-value\">");
        html.push_str(&self.metadata.total_memory_used_mb.to_string());
        html.push_str("MB</div>\n");
        html.push_str("      </div>\n");

        html.push_str("      <div class=\"stat\">\n");
        html.push_str("        <div class=\"stat-label\">Completed</div>\n");
        html.push_str("        <div class=\"stat-value\">");
        html.push_str(&self.metadata.completed_count.to_string());
        html.push_str("</div>\n");
        html.push_str("      </div>\n");

        html.push_str("      <div class=\"stat\">\n");
        html.push_str("        <div class=\"stat-label\">Errors</div>\n");
        html.push_str("        <div class=\"stat-value\">");
        html.push_str(&self.metadata.error_count.to_string());
        html.push_str("</div>\n");
        html.push_str("      </div>\n");

        html.push_str("    </div>\n");
        html.push_str("  </div>\n");

        html.push_str("</body>\n");
        html.push_str("</html>\n");

        html
    }
}

fn create_dynamic_graph(title: String) -> DynamicGraph {
    DynamicGraph::new(title)
}

fn render_dynamic_html(graph: DynamicGraph) -> String {
    graph.render_html()
}

// Helper trait for cloning
trait ExecutionStatusClone {
    fn clone(&self) -> ExecutionStatus;
}

impl ExecutionStatusClone for ExecutionStatus {
    fn clone(&self) -> ExecutionStatus {
        match self {
            ExecutionStatus::Pending => ExecutionStatus::Pending,
            ExecutionStatus::Executing => ExecutionStatus::Executing,
            ExecutionStatus::Completed => ExecutionStatus::Completed,
            ExecutionStatus::Error => ExecutionStatus::Error,
            ExecutionStatus::Skipped => ExecutionStatus::Skipped
        }
    }
}

trait DynamicNodeClone {
    fn clone(&self) -> DynamicNode;
}

impl DynamicNodeClone for DynamicNode {
    fn clone(&self) -> DynamicNode {
        DynamicNode {
            id: self.id.clone(),
            label: self.label.clone(),
            value: match &self.value {
                Option::Some(v) => Option::Some(v.clone()),
                Option::None => Option::None
            },
            status: self.status.clone(),
            execution_time_ms: self.execution_time_ms,
            color: self.color.clone()
        }
    }
}

