test "executor_simple_code" {
    let bridge = ExecutorBridge::new();
    let request = ExecutionRequest {
        code: "fn add(a: i32, b: i32) -> i32 { a + b }".to_string(),
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };
    let result = bridge.execute(request);
    match result {
        Result::Ok(res) => assert res.status == "success",
        Result::Err(_) => assert false
    }
}

test "executor_compile_error" {
    let bridge = ExecutorBridge::new();
    let request = ExecutionRequest {
        code: "fn broken { ".to_string(),
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };
    let result = bridge.execute(request);
    match result {
        Result::Ok(_) => assert false,
        Result::Err(e) => assert e.contains("Compilation") || e.contains("Mismatch")
    }
}

test "executor_timeout" {
    let bridge = ExecutorBridge::new();
    let request = ExecutionRequest {
        code: "fn loop_fn() { loop { } }".to_string(),
        inputs: vec![],
        timeout_ms: -100,
        sandbox_level: SandboxLevel::Standard
    };
    let result = bridge.execute(request);
    match result {
        Result::Ok(_) => assert false,
        Result::Err(e) => assert e.contains("Invalid") || e.len() > 0
    }
}

test "executor_sandbox_violation" {
    let bridge = ExecutorBridge::new();
    let request = ExecutionRequest {
        code: "fn restricted() { }".to_string(),
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Restricted
    };
    let result = bridge.execute(request);
    assert result.is_ok() || result.is_err();
}

test "executor_memory_limit" {
    let bridge = ExecutorBridge::new();
    let huge_code = "fn huge() { let x = vec![0; 1000000]; }".to_string();
    let request = ExecutionRequest {
        code: huge_code,
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };
    let result = bridge.execute(request);
    // 메모리가 너무 크면 에러
    match result {
        Result::Ok(_) => assert false,
        Result::Err(e) => assert e.contains("Out") || e.len() > 0
    }
}

test "executor_caching" {
    let bridge = ExecutorBridge::new();
    let code = "fn add(a: i32, b: i32) -> i32 { a + b }".to_string();
    let request = ExecutionRequest {
        code: code.clone(),
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };
    let result1 = bridge.execute(request.clone());
    let result2 = bridge.execute(request);

