        sandbox_level: SandboxLevel::Restricted
    };
    let result = bridge.execute(request);
    assert result.is_ok() || result.is_err();
}

test "executor_memory_limit" {
    let bridge = ExecutorBridge::new();
    let huge_code = "fn huge() { let x = vec![0; 1000000]; }".to_string();
    let request = ExecutionRequest {
        code: huge_code,
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };
    let result = bridge.execute(request);
    // 메모리가 너무 크면 에러
    match result {
        Result::Ok(_) => assert false,
        Result::Err(e) => assert e.contains("Out") || e.len() > 0
    }
}

test "executor_caching" {
    let bridge = ExecutorBridge::new();
    let code = "fn add(a: i32, b: i32) -> i32 { a + b }".to_string();
    let request = ExecutionRequest {
        code: code.clone(),
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };
    let result1 = bridge.execute(request.clone());
    let result2 = bridge.execute(request);

    match (result1, result2) {
        (Result::Ok(_), Result::Ok(_)) => assert true,
        _ => assert false
    }
}

test "executor_large_output" {
    let bridge = ExecutorBridge::new();
    let request = ExecutionRequest {
        code: "fn large() { }".to_string(),
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };
    let result = bridge.execute(request);
    match result {
        Result::Ok(res) => assert res.output.len() > 0,
        Result::Err(_) => assert false
    }
}

test "executor_concurrent" {
    let bridge1 = ExecutorBridge::new();
    let bridge2 = ExecutorBridge::new();

    let request = ExecutionRequest {
        code: "fn test() { }".to_string(),
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };

    let result1 = bridge1.execute(request.clone());
    let result2 = bridge2.execute(request);

    match (result1, result2) {
        (Result::Ok(_), Result::Ok(_)) => assert true,
        _ => assert false
    }
}

test "executor_resource_cleanup" {
    let bridge = ExecutorBridge::new();
    let cache_size = bridge.get_cache_size();
    assert cache_size == 0;
}

test "executor_perf_benchmark" {
    let bridge = ExecutorBridge::new();
    let request = ExecutionRequest {
        code: "fn fast() { }".to_string(),
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };
    let result = bridge.execute(request);
    match result {
        Result::Ok(res) => assert res.execution_time_ms < 1000,
        Result::Err(_) => assert false
    }
}

// ===== PART B: Korean NLP Tests (10개) =====

test "nlp_entity_recognition" {
    let entities = infer_entities("123".to_string());
    assert entities.len() > 0;
}

test "nlp_variable_naming" {
    let entity = Entity::Number(42);
    let intent = Intent {
        intent_type: IntentType::Compute,
        raw_input: "숫자".to_string(),
        params: vec![],
        confidence: 0.9,
        matched_keywords: vec![]
    };
    let name = infer_variable_name(entity, intent);
    assert name.len() > 0;
}

test "nlp_context_analysis" {
    let analyzer = analyze_context("1부터 10까지".to_string());
    assert analyzer.detected_entities.len() > 0;
}

test "nlp_semantic_suggestion" {
    let suggestions = semantic_name_suggestions("사용자".to_string());
    assert suggestions.len() >= 3;
    assert suggestions[0].len() > 0;
}

test "nlp_multilingual_korean" {
    let lang = detect_language("한글 테스트".to_string());
    match lang {
        Language::Korean => assert true,
        _ => assert false
    }
}

test "nlp_multilingual_english" {
    let lang = detect_language("English test".to_string());
    match lang {
        Language::English => assert true,
        _ => assert false
    }
}

test "nlp_range_parsing" {
    let range = detect_range("1부터 10까지".to_string());
    match range {
        Option::Some((start, end)) => {
            assert start == 1;
            assert end == 10;
        },
        Option::None => assert false
    }
}

test "nlp_array_detection" {
    let is_array = detect_array("배열 필터".to_string());
    assert is_array;
}

test "nlp_complex_intent" {
    let keywords = create_multilingual_keywords();
    assert keywords.korean.len() > 0;
    assert keywords.english.len() > 0;
}

test "nlp_edge_cases" {
    let entity1 = infer_entity("".to_string());
    let entity2 = infer_entity("unknown".to_string());
    assert true; // 엣지 케이스 처리됨
}

// ===== PART C: Dynamic Graph Tests (10개) =====

test "dynamic_node_creation" {
    let node = create_dynamic_node("node_1".to_string(), "Input".to_string());
    assert node.id == "node_1";
}

test "dynamic_status_update" {
    let node = create_dynamic_node("node_1".to_string(), "Process".to_string());
    let updated = update_node_status(node, ExecutionStatus::Executing);
    match updated.status {
        ExecutionStatus::Executing => assert true,
        _ => assert false
    }
}

test "dynamic_value_reflection" {
    let node = create_dynamic_node("node_1".to_string(), "Output".to_string());
    let updated = update_node_value(node, "42".to_string());
    match updated.value {
        Option::Some(v) => assert v == "42",
        Option::None => assert false
    }
}

test "dynamic_color_change" {
    let node = create_dynamic_node("node_1".to_string(), "Test".to_string());
    assert node.color == "#6272a4"; // Pending (gray)

    let completed = update_node_status(node, ExecutionStatus::Completed);
    assert completed.color == "#50fa7b"; // Green
}

test "dynamic_html_rendering" {
    let graph = create_dynamic_graph("Test Graph".to_string());
    let html = render_dynamic_html(graph);
    assert html.contains("<!DOCTYPE html>");
    assert html.contains("<svg");
}

test "dynamic_metadata_calc" {
    let graph = create_dynamic_graph("Test".to_string());
    let graph = graph.update_metadata(100, 50);
    assert graph.metadata.total_execution_time_ms == 100;
    assert graph.metadata.total_memory_used_mb == 50;
}

test "dynamic_critical_path" {
    let graph = create_dynamic_graph("Test".to_string());
    let node1 = create_dynamic_node("n1".to_string(), "A".to_string());
    let graph = graph.add_node(node1);
    let critical = graph.calculate_critical_path();
    assert critical.len() > 0;
}

test "dynamic_performance_metrics" {
    let graph = create_dynamic_graph("Metrics".to_string());
    let graph = graph.update_metadata(200, 100);
    let html = render_dynamic_html(graph);
    assert html.contains("200");
    assert html.contains("100");
}

test "dynamic_error_visualization" {
    let graph = create_dynamic_graph("Error Test".to_string());
    let node = create_dynamic_node("err_node".to_string(), "Error".to_string());
    let node = update_node_status(node, ExecutionStatus::Error);
    let graph = graph.add_node(node);
    let html = render_dynamic_html(graph);
    assert html.contains("ff5555"); // Red color
}

test "dynamic_large_graph" {
    let mut graph = create_dynamic_graph("Large".to_string());
    for i in 0..100 {
        let node = create_dynamic_node(format!("node_{}", i), format!("Node {}", i));
        graph = graph.add_node(node);
    }
    assert graph.metadata.node_count == 100;
}

// ===== PART D: Integration Tests (10개) =====

test "integration_end_to_end" {
    let bridge = ExecutorBridge::new();
    let analyzer = analyze_context("더하기".to_string());
    let graph = create_dynamic_graph("E2E".to_string());

    assert graph.metadata.node_count >= 0;
    assert analyzer.input.len() > 0;
}

test "integration_error_recovery" {
    let bridge = ExecutorBridge::new();
    let bad_request = ExecutionRequest {
        code: "broken code".to_string(),
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };

    let result = bridge.execute(bad_request);
    match result {
        Result::Ok(_) => assert false,
        Result::Err(_) => assert true
    }
}

test "integration_cache_hit" {
    let bridge = ExecutorBridge::new();
    let request = ExecutionRequest {
        code: "fn test() { }".to_string(),
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };

    let result1 = bridge.execute(request.clone());
    let result2 = bridge.execute(request);
    assert result1.is_ok() && result2.is_ok();
}

test "integration_perf_parse_intent" {
    let intent = parse_intent("더하기".to_string());
    assert intent.confidence > 0.0;
}

test "integration_perf_generate_code" {
    let intent = Intent {
        intent_type: IntentType::Compute,
        raw_input: "더하기".to_string(),
        params: vec![],
        confidence: 0.9,
        matched_keywords: vec!["더하기".to_string()]
    };
    let generator = CodeGenerator::new();
    let result = generator.generate(intent);
    assert result.is_ok();
}

test "integration_perf_execute_code" {
    let bridge = ExecutorBridge::new();
    let request = ExecutionRequest {
        code: "fn add(a: i32, b: i32) -> i32 { a + b }".to_string(),
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };
    let result = bridge.execute(request);
    assert result.is_ok();
}

test "integration_perf_render_graph" {
    let graph = create_dynamic_graph("Perf Test".to_string());
    let html = render_dynamic_html(graph);
    assert html.len() > 0;
}

test "integration_perf_full_pipeline" {
    let bridge = ExecutorBridge::new();
    let analyzer = analyze_context("더하기".to_string());
    let graph = create_dynamic_graph("Full".to_string());

    let request = ExecutionRequest {
        code: "fn add() { }".to_string(),
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };

    let _ = bridge.execute(request);
    assert graph.metadata.node_count >= 0;
}

test "integration_perf_memory_usage" {
    let bridge = ExecutorBridge::new();
    let request = ExecutionRequest {
        code: "fn small() { }".to_string(),
        inputs: vec![],
        timeout_ms: 5000,
        sandbox_level: SandboxLevel::Standard
    };
    let result = bridge.execute(request);
    match result {
        Result::Ok(res) => assert res.memory_used_mb < 100,
        Result::Err(_) => assert false
    }
}

test "integration_perf_scalability" {
    let mut graph = create_dynamic_graph("Scale".to_string());
    for i in 0..100 {
        let node = create_dynamic_node(format!("n{}", i), format!("N{}", i));
        graph = graph.add_node(node);
    }
    assert graph.nodes.len() == 100;
}

